from typing import List, Tuple, Dict

def merge_bookings(bookings: List[Tuple[int, int, str]]) -> Dict[str, List[Tuple[int, int]]]:
    merged_bookings = {}

    # Sort bookings by start time
    sorted_bookings = sorted(bookings, key=lambda x: x[0])

    for booking in sorted_bookings:
        room, start, end = booking

        if room not in merged_bookings:
            merged_bookings[room] = [(start, end)]
        else:
            # Merge overlapping/adjacent bookings
            last_start, last_end = merged_bookings[room][-1]
            if last_end >= start:
                merged_bookings[room][-1] = (last_start, max(last_end, end))
            else:
                merged_bookings[room].append((start, end))

    return merged_bookings
